import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';

import { UPLOADS_ROOT, UPLOAD_DIRS } from '../config.js';

/**
 * Resolve a stored relative media path (e.g. "images/ab12.jpg") to an absolute
 * path, refusing anything that escapes the uploads directory. Stored paths are
 * generated by the server, but a poisoned row must never turn into an unlink
 * somewhere else on disk.
 */
export function resolveUploadPath(relPath) {
  if (typeof relPath !== 'string' || relPath === '') {
    throw new Error('Empty media path');
  }
  if (relPath.includes('\0')) {
    throw new Error('Invalid media path');
  }
  const absolute = path.resolve(UPLOADS_ROOT, relPath);
  if (absolute !== UPLOADS_ROOT && !absolute.startsWith(UPLOADS_ROOT + path.sep)) {
    throw new Error(`Refusing to touch a path outside uploads: ${relPath}`);
  }
  return absolute;
}

/** Delete one stored media file. Never throws: a missing file is not an error. */
export async function safeUnlink(relPath) {
  let absolute;
  try {
    absolute = resolveUploadPath(relPath);
  } catch (err) {
    console.error('[uploads] refused to delete', relPath, err.message);
    return false;
  }
  try {
    await fsp.unlink(absolute);
    return true;
  } catch (err) {
    if (err.code !== 'ENOENT') {
      console.error('[uploads] failed to delete', relPath, err.message);
    }
    return false;
  }
}

export async function safeUnlinkAll(relPaths) {
  await Promise.all(relPaths.map((p) => safeUnlink(p)));
}

/** Every file currently sitting in the upload directories, as relative paths. */
export function listStoredFiles() {
  const out = [];
  for (const [kind, dir] of Object.entries(UPLOAD_DIRS)) {
    let entries = [];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      if (entry.isFile() && !entry.name.startsWith('.')) {
        out.push(`${kind === 'image' ? 'images' : 'videos'}/${entry.name}`);
      }
    }
  }
  return out;
}

/** Files on disk that no media row references. */
export function findOrphans(referencedPaths) {
  const referenced = new Set(referencedPaths);
  return listStoredFiles().filter((rel) => !referenced.has(rel));
}
